class Solution:

	def printCousins(self, root, node_to_find):
		q = [root]
		flag = 0
		while len(q) > 0:
			l = len(q)
			for i in range(l):
				temp = q[0]
				q.pop(0)
				if temp.left != None and temp.left == node_to_find:
					flag = 1
					continue
				elif temp.right != None and temp.right == node_to_find:
					flag = 1
					continue
				if temp.left != None:
					q.append(temp.left)
				if temp.right != None:
					q.append(temp.right)
			if flag == 1:
				break
		for i in range(len(q)):
			q[i] = q[i].data
		if len(q) == 0:
			return [-1]
		return q
